<?php defined('BASEPATH') or exit('No direct script access allowed');$pxExtra=['discussion_id'=>$dt['id'],'discussion_revision'=>$dt['revision'],'discussion_post_id'=>$post['id'],'discussion_post_revision'=>$post['content_revision']];$pxWritable=$ds['can_edit']&&(int)$dt['active']===1&&(int)$post['active']===1&&$dt['status']==='open'&&$dp['status']==='active';$pxOwn=$post['author_type']==='staff'&&(int)$post['staff_id']===(int)$actor; ?>
<?php if((int)$post['active']===0){ ?><p>Comentário excluído; histórico preservado.</p><?php }if($pxWritable&&$pxOwn){if((int)$post['content_revision']<100){echo form_open($url('', 'discussion_edit'),['class'=>'project-discussion-own-edit']);$discussionHidden('discussion_edit',$pxExtra); ?><label>Nova versão da sua mensagem<textarea name="discussion_body" rows="4" maxlength="8000" style="display:block;width:100%;box-sizing:border-box" required><?= $esc($post['body']); ?></textarea></label><p>A alteração preserva o histórico e volta a mensagem para audiência privada. Publique novamente após revisar.</p><button type="submit">Salvar minha nova versão privada</button><?= form_close(); ?><?php }else{ ?><p>Limite de100 versões alcançado; a exclusão sem respostas e os anexos continuam sujeitos às permissões atuais.</p><?php }echo form_open($url('', 'discussion_delete',$post['id']),['class'=>'project-discussion-own-delete']);$discussionHidden('discussion_delete',$pxExtra); ?><button type="submit">Excluir minha mensagem sem respostas</button><?= form_close(); ?><?php echo form_open_multipart($url(),['class'=>'project-discussion-file-upload']);$discussionHidden('discussion_file_upload',$pxExtra); ?><label>Anexo privado da sua mensagem<input type="file" name="discussion_file" accept="application/pdf,image/png,image/jpeg" required></label><p>Privado para seu autor e a equipe. PDF2 MiB ou PNG/JPEG512 KiB e1600 pixels. Limite20 anexos/20 MiB por conversa, incluindo ocultos.</p><button type="submit">Anexar arquivo interno ao comentário</button><?= form_close(); ?><?php } ?>
<?php foreach($post['files']??[] as $file){echo form_open($url(),['class'=>'project-discussion-file-download']);$discussionHidden('discussion_file_download',$pxExtra+['file_key'=>$file['file_key']]); ?><?php if($file['audience']!=='private'&&!$file['publication_current']){ ?><p>Compartilhamento anterior indisponível nesta versão. Revise a audiência da mensagem e publique novamente este anexo.</p><?php } ?><span><?= $esc($file['filename']); ?> · <?= $esc($file['author_name']); ?> · <?= (int)$file['byte_size']; ?> bytes</span><button type="submit">Baixar anexo do comentário</button><?= form_close(); ?><?php if($pxWritable){echo form_open($url(),['class'=>'project-discussion-file-publication']);$discussionHidden('discussion_file_audience',$pxExtra+['file_key'=>$file['file_key']]); ?><label>Audiência deste anexo<select name="discussion_file_audience"><option value="private" <?= $file['audience']==='private'?'selected':''; ?>>Privado para o autor e a equipe</option><?php if($dt['author_type']==='contact'&&in_array($post['audience'],['author','public'],true)){ ?><option value="author" <?= $file['audience']==='author'?'selected':''; ?>>Compartilhar também com o autor da conversa</option><?php }if((int)$dt['visible']===1&&$post['audience']==='public'){ ?><option value="public" <?= $file['audience']==='public'?'selected':''; ?>>Publicar para contatos autorizados deste cliente</option><?php } ?></select></label><p>Compartilha somente esta versão do comentário. Alterar seu texto invalida o compartilhamento anterior do anexo.</p><button type="submit">Salvar audiência do anexo</button><?= form_close(); ?><?php }} ?>
